// Map between the lines of the sources generated by cblt (build/<suite>.cbl)
// and their origin (the line of the .cblt or of the original program in an
// in-program copy). "cobalto debug" writes it to build/<suite>.lines.json.

import * as fs from 'fs';
import * as path from 'path';
import { schemaProblem } from './schema';

export interface Origin {
  file: string;
  line: number;
}

export class LineMap {
  /** generated file (absolute path) -> origin per line (index 0 = line 1) */
  private readonly genToOrigin = new Map<string, (Origin | undefined)[]>();
  /** origin file (abs) -> generated file (abs) -> origin line -> first generated line */
  private readonly originToGen = new Map<string, Map<string, Map<number, number>>>();

  constructor(readonly root: string) {}

  static load(jsonPath: string, root: string, log?: (s: string) => void): LineMap | undefined {
    let data: { schema?: number; cobalto?: string; origins?: Record<string, ([string, number] | null)[]> };
    try {
      data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
    } catch {
      return undefined;
    }
    const problem = schemaProblem(data, jsonPath);
    if (problem) {
      log?.(problem);
      return undefined;
    }
    const lm = new LineMap(root);
    for (const [gen, origins] of Object.entries(data.origins ?? {})) {
      const genAbs = path.resolve(root, gen);
      const list = origins.map((o) => (o ? { file: path.resolve(root, o[0]), line: o[1] } : undefined));
      lm.genToOrigin.set(genAbs, list);
      list.forEach((o, i) => {
        if (!o) {
          return;
        }
        let byGen = lm.originToGen.get(o.file);
        if (!byGen) {
          byGen = new Map();
          lm.originToGen.set(o.file, byGen);
        }
        let lines = byGen.get(genAbs);
        if (!lines) {
          lines = new Map();
          byGen.set(genAbs, lines);
        }
        if (!lines.has(o.line)) {
          lines.set(o.line, i + 1);
        }
      });
    }
    log?.(`line map: ${lm.genToOrigin.size} generated, ${lm.originToGen.size} origins (${jsonPath})`);
    return lm;
  }

  isGenerated(absPath: string): boolean {
    return this.genToOrigin.has(absPath);
  }

  originOf(absPath: string, line: number): Origin | undefined {
    const list = this.genToOrigin.get(absPath);
    return list && line >= 1 && line <= list.length ? list[line - 1] : undefined;
  }

  /** Generated files that contain lines originating in absPath. */
  generatedFor(absPath: string): Map<string, Map<number, number>> | undefined {
    return this.originToGen.get(absPath);
  }

  generatedFiles(): string[] {
    return [...this.genToOrigin.keys()];
  }
}
